import Axios from '@/server'
import type { Result } from '@/server/types'
import { OrderManagementTypes } from './types'

// ==================== 【订单管理】 ====================

/**
 * 【订单管理】获取订单详情
 * @param orderId 订单ID
 */
export const getOrderDetail = (orderId: number) =>
  Axios.request<Result<OrderManagementTypes.DetailOrderRes>>({
    url: `/admin/order-management/order/${orderId}/detail`,
    method: 'GET'
  })

/**
 * 【订单管理】获取订单客诉记录
 * @param orderId 订单ID
 */
export const getOrderComplaintRecord = (orderId: number) =>
  Axios.request<Result<OrderManagementTypes.OrderComplaintRecordRes>>({
    url: `/admin/order-management/order/${orderId}/order-complaint-record`,
    method: 'GET'
  })

/**
 * 【订单管理】获取订单操作日志
 * @param orderId 订单ID
 */
export const getOrderOperationLogs = (orderId: number) =>
  Axios.request<Result<OrderManagementTypes.OperationLogsOrderRes>>({
    url: `/admin/order-management/order/${orderId}/order-operation-log`,
    method: 'GET'
  })

/**
 * 【订单管理】回复订单客诉
 * @param orderId 订单ID
 * @param data 回复内容
 */
export const replyOrderComplaint = (
  orderId: number,
  data: OrderManagementTypes.ReplyOrderComplaintReq
) =>
  Axios.request<Result>({
    url: `/admin/order-management/order/${orderId}/reply-order-complaint`,
    method: 'POST',
    data
  })

/**
 * 【订单管理】获取订单列表
 * @param params 查询参数
 */
export const getOrderList = (params?: OrderManagementTypes.OrderListReq) =>
  Axios.request<Result<OrderManagementTypes.OrderListRes>>({
    url: '/admin/order-management/order/list',
    method: 'GET',
    params
  })

